        let url = "https://api.elevenlabs.com/v1/text-to-speech";
        let data = serde_json::json!({
            "text": clipboard_content,
            "voice": "en-US-Wavenet-A",
            "format": "mp3"
        });

        let response = client
            .post(url)
            .header("Authorization", format!("Bearer {}", api_key))
            .json(&data)
            .send()?
            .error_for_status()?
            .json::<TtsResponse>()
            .await?;

        Ok(response)
