In Swift, you can create a similar class using `CALayer` and `UIImageView`. Here's an example:

```swift
import UIKit

class StackedImageViews: UIView {
    private var imageViews: [UIImageView] = []
    private let iconScale: CGFloat = 0.7

    init(images: [UIImage], iconScale: CGFloat = 0.7) {
        super.init(frame: .zero)
        self.iconScale = iconScale
        setupLayers(images: images)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    private func setupLayers(images: [UIImage]) {
        for (index, image) in images.enumerated() {
            let imageView = UIImageView(image: image)
            imageView.contentMode = .scaleAspectFit
            imageView.translatesAutoresizingMaskIntoConstraints = false
            addSubview(imageView)
            NSLayoutConstraint.activate([
                imageView.widthAnchor.constraint(equalToConstant: bounds.width * iconScale),
                imageView.heightAnchor.constraint(equalToConstant: bounds.width * iconScale),
                imageView.centerXAnchor.constraint(equalTo: centerXAnchor),
                imageView.centerYAnchor.constraint(equalTo: centerYAnchor)
            ])
            imageViews.append(imageView)
        }
        if imageViews.count > 1 {
            let secondImageView = imageViews[1]
            secondImageView.center = CGPoint(x: secondImageView.center.x, y: secondImageView.center.y - bounds.width * iconScale)
        }
    }

    override func layoutSubviews() {
        super.layoutSubviews()
        setupLayers(images: imageViews.map { $0.image })
    }
}
```

