```javascript
function mergeArrays(arr1, arr2) {
  const merged = [];

  // Create a Set to store unique combinations of stepId and fieldId
  const uniqueCombinationSet = new Set();

  // Iterate through the first array
  arr1.forEach((obj1) => {
    const combination = `${obj1.stepId}-${obj1.fieldId}`;

    // If the combination is not already in the Set, add the object to the merged array and add the combination to the Set
    if (!uniqueCombinationSet.has(combination)) {
      uniqueCombinationSet.add(combination);
      merged.push({ ...obj1, ...(arr2.find((obj2) => obj1.stepId === obj2.stepId && obj1.fieldId === obj2.fieldId) || {}) });
    }
  });

  // Iterate through the second array and add objects that are not already in the merged array
  arr2.forEach((obj2) => {
    const combination = `${obj2.stepId}-${obj2.fieldId}`;

    // If the combination is not already in the Set, add the object to the merged array and add the combination to the Set
    if (!uniqueCombinationSet.has(combination)) {
      uniqueCombinationSet.add(combination);
      merged.push(obj2);
    }
  });

  return merged;
}

