To compare two Excel files and show discrepancies in Node.js, you can use a library like `xlsx` to read the Excel files and `lodash` for comparison. Here's a basic example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareExcelFiles(file1, file2) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet_name_list1 = workbook1.SheetNames;
  const sheet_name_list2 = workbook2.SheetNames;

  const sheetNames = _.intersection(sheet_name_list1, sheet_name_list2);

  const discrepancies = [];

  sheetNames.forEach(sheetName => {
    const data1 = XLSX.utils.sheet_to_json(workbook1.Sheets[sheetName]);
    const data2 = XLSX.utils.sheet_to_json(workbook2.Sheets[sheetName]);

    const differences = _.differenceWith(data1, data2, _.isEqual);

    if (differences.length > 0) {
      discrepancies.push({ sheetName, differences });
    }
  });

  return discrepancies;
}

// Usage
compareExcelFiles('file1.xlsx', 'file2.xlsx')
  .then(discrepancies => {
    console.log(discrepancies);
  })
  .catch(error => {
    console.error(error);
  });
```

This script reads the Excel files, compares the sheets with the same name, and returns an array of objects containing the sheet name and an array of objects representing the discrepancies (different rows). Each object in the discrepancies array contains the row data as it appears in the two files.

